/*
 * Description:
 *   Include the production adapter against RT/MMIO stubs generated by the
 *   runner. Verify shared-clock ownership, independent DMA and write policy.
 *   This is a software model; it cannot validate electrical card timing.
 */

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ls2k_sdio_test_stubs.h"
#include "drv_sdio.c"

static uint32_t host_regs[2][0x810 / 4];
static uint32_t clock_scale;
static uint32_t clock_sample;
static uint32_t mux[2];
static uint32_t other_regs[4];
static unsigned int now;
static unsigned int notifications;
static unsigned int transfer_count;
static struct rt_mmcsd_host allocated_hosts[2];
static unsigned int allocations;
static unsigned int reset_assertions;
static unsigned int query_count[2];
static unsigned int query_behavior[2];
static int mirror_orders = 1;

uint32_t *sdio_test_register(uintptr_t address)
{
    for (unsigned int port = 0; port < 2; ++port)
    {
        uintptr_t base = 0x16140000UL + port * 0x8000UL;

        if (address >= base && address < base + sizeof(host_regs[0]))
        {
            return &host_regs[port][(address - base) / 4];
        }
    }

    switch (address)
    {
    case LS2K0300_CLOCK_SAMPLE:
        return &clock_sample;

    case LS2K0300_CLOCK_SCALE:
        return &clock_scale;

    case 0x160004a4:
        return &mux[0];

    case 0x160004a8:
        return &mux[1];

    case 0x16000424:
        return &other_regs[0];

    case 0x16000118:
        return &other_regs[1];

    case 0x16000120:
        return &other_regs[2];

    default:
        assert(!"unexpected MMIO address");
        return &other_regs[3];
    }
}

uintptr_t sdio_test_physical(uintptr_t pointer)
{
    if (pointer >= (uintptr_t)storage && pointer <= (uintptr_t)(storage + SD_HOST_COUNT))
    {
        return 0x00800000UL + pointer - (uintptr_t)storage;
    }

    if (pointer >= (uintptr_t)handoff_query &&
        pointer < (uintptr_t)(handoff_query + SD_HOST_COUNT))
    {
        return 0x00900000UL + pointer - (uintptr_t)handoff_query;
    }

    return pointer;
}

struct rt_mmcsd_host *mmcsd_alloc_host(void)
{
    assert(allocations < 2);
    return &allocated_hosts[allocations++];
}

void mmcsd_change(struct rt_mmcsd_host *host)
{
    assert(host->private_data);
    ++notifications;
}

uint32_t rt_tick_get(void)
{
    return now;
}

void rt_thread_mdelay(unsigned int milliseconds)
{
    now += milliseconds;

    for (unsigned int port = 0; port < 2; ++port)
    {
        static const unsigned int orders[2] = {LSD_DMA_READ, LSD_DMA_WRITE};

        if (!(other_regs[2] & (1U << 27)) ||
            !(other_regs[2] & (1U << (13 + port))))
        {
            ++reset_assertions;
        }

        for (unsigned int direction = 0; direction < 2; ++direction)
        {
            uint32_t *order = &host_regs[port][orders[direction] / 4];
            uintptr_t physical = *order & ~31U;

            if (!(*order & LSD_DMA_QUERY) || query_behavior[port] == 1)
            {
                continue;
            }

            assert(physical >= 0x00900000UL);
            assert(physical < 0x00900000UL + sizeof(handoff_query));
            struct ls2k_sdio_desc *query = (void *)((uintptr_t)handoff_query +
                                                   physical - 0x00900000UL);
            ++query_count[port];

            if (query_behavior[port] != 2)
            {
                memset(query, 0, sizeof(*query));
                query->command = 0x509;

                if (query_behavior[port] == 3)
                {
                    query->command = 0x529; /* Stale DONE while reading. */
                }
                else if (query_behavior[port] == 4)
                {
                    query->next = 0x80001;
                }
                else if (query_behavior[port] == 5)
                {
                    query->command = 0x501;
                }
                else if (query_behavior[port] == 6)
                {
                    query->command = 0x209; /* Payload write still active. */
                }
            }

            *order &= ~LSD_DMA_QUERY;

            if (mirror_orders)
            {
                host_regs[port][orders[1 - direction] / 4] = *order;
            }
        }
    }
}

int rt_sem_take(struct rt_semaphore *semaphore, unsigned int milliseconds)
{
    (void)semaphore;
    now += milliseconds;
    return 0;
}

/* These boundaries deliberately stub the engine, which has its own production
 * MMIO regression. The adapter must reject unsafe requests before this call. */
int ls2k_sdio_reset(struct ls2k_sdio *sd)
{
    (void)sd;
    return 0;
}

int ls2k_sdio_clock(struct ls2k_sdio *sd, uint32_t requested)
{
    sd->clock = requested;
    return 0;
}

int ls2k_sdio_transfer(struct ls2k_sdio *sd, struct ls2k_sdio_command *command)
{
    (void)sd;
    ++transfer_count;
    assert(command->timeout_ms > 0 && command->timeout_ms <= 10000);
    return 0;
}

int ls2k_sdio_wait_ready(struct ls2k_sdio *sd, uint16_t rca, unsigned int timeout)
{
    (void)sd;
    assert(rca && timeout);
    return 0;
}

static void initialize(void)
{
    memset(host_regs, 0, sizeof(host_regs));
    memset(other_regs, 0, sizeof(other_regs));
    memset(mux, 0, sizeof(mux));
    memset(devices, 0, sizeof(devices));
    memset(allocated_hosts, 0, sizeof(allocated_hosts));
    allocations = notifications = transfer_count = now = 0;
    reset_assertions = 0;
    memset(query_count, 0, sizeof(query_count));
    memset(query_behavior, 0, sizeof(query_behavior));
    memset(handoff_snapshot, 0, sizeof(handoff_snapshot));
    handoff_attempted = 0;
    mirror_orders = 1;
    other_regs[0] = other_regs[1] = other_regs[2] = UINT32_MAX;
    clock_sample = 0x8c; /* Native eMMC0, SD1, fixed 3.3 V pads. */
    clock_scale = 0x71777777;
    host_regs[0][LSD_CON / 4] = LSD_CLOCK;
    host_regs[1][LSD_CON / 4] = LSD_CLOCK;
}

#ifndef SDIO_TEST_SINGLE
static void check_rejected(struct ls2k_sd_host *dev, unsigned int index,
                           uint32_t argument, struct rt_mmcsd_data *data)
{
    struct rt_mmcsd_cmd command = {0};
    unsigned int before = transfer_count;

    command.cmd_code = index;
    command.arg = argument;
    command.data = data;
    command.flags = RESP_R1B;
    sd_command(dev, &command);
    assert(command.err < 0 && transfer_count == before);

    if (data)
    {
        assert(data->err == command.err && data->bytes_xfered == 0);
    }
}

#endif

#ifdef SDIO_TEST_SINGLE
int main(void)
{
    uint32_t input;

    initialize();
    assert(sd_shared_clock(clock_sample, &input) == -RT_EBUSY);
    assert(!reset_assertions && other_regs[2] == UINT32_MAX);
    initialize();
    host_regs[0][LSD_CON / 4] = 0;
    host_regs[0][LSD_DMA_READ / 4] = 0x00800001;
    host_regs[1][LSD_DMA_READ / 4] = 0x00804001;
    assert(sd_shared_clock(clock_sample, &input) == -RT_EBUSY);
    assert(!query_count[0] && !query_count[1]);
    clock_scale = 0x72777777;
    assert(sd_shared_clock(clock_sample, &input) == 0);
    assert(input == 100000000 && !reset_assertions);
    assert(!query_count[0] && query_count[1] == 1);
    assert(host_regs[0][LSD_DMA_READ / 4] == 0x00800001);
    assert(other_regs[2] == UINT32_MAX);

    initialize();
    host_regs[0][LSD_CON / 4] = 0;
    assert(sd_shared_clock(clock_sample, &input) == 0);
    assert(input == 100000000 && clock_scale == 0x72777777);
    assert(!query_count[0] && !query_count[1] && !reset_assertions);
    assert(other_regs[0] == UINT32_MAX && other_regs[1] == UINT32_MAX &&
           other_regs[2] == UINT32_MAX);
    puts("SDIO adapter: single-host handoff preserves the unowned port PASS");
    return 0;
}
#else
int main(void)
{
    struct rt_mmcsd_cmd command = {0};
    struct rt_mmcsd_data write = {.flags = DATA_DIR_WRITE};
    uint32_t input;

    initialize();
    /* Both windows mirror one engine on the real board. All initial orders
     * must be captured before any QUERY changes their addresses. */
    for (unsigned int port = 0; port < 2; ++port)
    {
        host_regs[port][LSD_DMA_READ / 4] = 0x00080000;
        host_regs[port][LSD_DMA_WRITE / 4] = 0x00080000;
    }

    assert(rt_hw_sdio_init() == 0);
    assert(!reset_assertions && query_count[0] == 2 && query_count[1] == 2);
    assert(handoff_snapshot[0].low[0] == 0x80000 &&
           handoff_snapshot[0].low[1] == 0x80000 &&
           handoff_snapshot[1].low[0] == 0x80000 &&
           handoff_snapshot[1].low[1] == 0x80000);
    assert(other_regs[2] == UINT32_MAX);
    assert(notifications == 2 && allocations == 2);
    assert((clock_scale >> 24 & 15) == 2);
    assert(devices[0].controller.input_clock == 100000000);
    assert(devices[1].controller.input_clock == 100000000);
    assert(devices[0].controller.emmc && !devices[1].controller.emmc);
    assert(devices[0].controller.dma != devices[1].controller.dma);
    assert(devices[1].controller.dma_address - devices[0].controller.dma_address == sizeof(storage[0]));
    assert(devices[0].irq == 31 && devices[1].irq == 32);
    assert(!strcmp(allocated_hosts[0].name, "mmc0"));
    assert(!strcmp(allocated_hosts[1].name, "mmc1"));
    assert(devices[0].max_width == 8 && devices[1].max_width == 4);
    assert((allocated_hosts[0].flags & MMCSD_BUSWIDTH_8) != 0);
    assert((host_regs[0][LSD_BUS_MODE / 4] & 3) == 0);
    assert((host_regs[1][LSD_BUS_MODE / 4] & 3) == 0);
    assert(mux[0] == 0xfff00000 && mux[1] == 0x000fffff);

    struct rt_mmcsd_io_cfg config =
    {
        .bus_width = MMCSD_BUS_WIDTH_8,
        .power_mode = 2,
        .clock = 52000000,
    };

    sd_iocfg(&allocated_hosts[0], &config);
    assert(config.clock == 25000000 && devices[0].controller.clock == 25000000);

    command.cmd_code = SEND_OP_COND;
    command.flags = RESP_R3;
    command.busy_timeout = UINT32_MAX; /* Optional field is not valid for R3. */
    sd_command(&devices[0], &command);
    assert(!command.err);
    check_rejected(&devices[1], SEND_OP_COND, 0, NULL);
    check_rejected(&devices[0], APP_CMD, 0, NULL);
    check_rejected(&devices[0], SEND_EXT_CSD, 0, NULL);
    check_rejected(&devices[0], 24, 0, &write);
    check_rejected(&devices[1], 25, 0, &write);
    check_rejected(&devices[0], 38, 0, NULL);
    check_rejected(&devices[0], 6, 0x03b30101, NULL); /* PARTITION_CONFIG */
    check_rejected(&devices[0], 6, 0x03210101, NULL); /* CACHE_CTRL=1 */
    check_rejected(&devices[0], 6, 0x03b70601, NULL); /* DDR width */
    check_rejected(&devices[0], 6, 0x03b90201, NULL); /* HS200 */
    check_rejected(&devices[0], 6, 0x83b70201, NULL); /* Reserved argument bits */
    command = (struct rt_mmcsd_cmd){.cmd_code = 6, .flags = RESP_R1B};
    const uint32_t allowed[] = {0x03b70001, 0x03b70201, 0x03b90101, 0x03210001};

    for (unsigned int i = 0; i < sizeof(allowed) / sizeof(allowed[0]); ++i)
    {
        command.arg = allowed[i];
        sd_command(&devices[0], &command);
        assert(!command.err);
    }

    initialize();
    host_regs[1][LSD_CMD / 4] = LSD_CMD_START;
    assert(sd_shared_clock(clock_sample, &input) == -RT_EBUSY);
    assert(clock_scale == 0x71777777 && host_regs[0][LSD_CON / 4] == LSD_CLOCK);
    initialize();
    host_regs[0][LSD_DMA_READ / 4] = LSD_DMA_START;
    assert(sd_shared_clock(clock_sample, &input) == -RT_EBUSY);
    assert(clock_scale == 0x71777777);
    initialize();
    clock_sample &= ~(1U << 3); /* A converted SD IP supports only four bits. */
    assert(rt_hw_sdio_init() == 0);
    assert(devices[0].max_width == 4);
    assert(!(allocated_hosts[0].flags & MMCSD_BUSWIDTH_8));
    assert((host_regs[0][LSD_BUS_MODE / 4] & 3) == 2);
    assert((mux[1] & 255) == 0);
    for (unsigned int behavior = 1; behavior <= 6; ++behavior)
    {
        initialize();
        host_regs[0][LSD_DMA_READ / 4] = 0x00800001;
        query_behavior[0] = behavior;
        assert(rt_hw_sdio_init() < 0);
        assert(!allocations && !notifications && !reset_assertions);
        assert(clock_scale == 0x71777777);
        assert(host_regs[0][LSD_CON / 4] == LSD_CLOCK);
        assert(host_regs[1][LSD_CON / 4] == LSD_CLOCK);
        assert(other_regs[2] == UINT32_MAX);
        struct ls2k_sdio_desc saved = handoff_query[0][0];
        assert(sd_shared_clock(clock_sample, &input) == -RT_EIO);
        assert(!memcmp(&saved, &handoff_query[0][0], sizeof(saved)));
    }

    initialize();
    host_regs[0][(LSD_DMA_READ + 4) / 4] = 1;
    assert(sd_shared_clock(clock_sample, &input) == -RT_EBUSY);
    assert(!query_count[0] && clock_scale == 0x71777777);
    initialize();
    host_regs[0][LSD_DMA_READ / 4] = LSD_DMA_64BIT;
    host_regs[0][(LSD_DMA_READ + 4) / 4] = 1;
    assert(sd_shared_clock(clock_sample, &input) == 0);
    assert(query_count[0] == 1); /* High-only valid address is not unused. */
    assert(handoff_snapshot[0].high[0] == 1);

    initialize();
    other_regs[0] &= ~(1U << 4);
    assert(sd_shared_clock(clock_sample, &input) == -RT_EBUSY);
    assert(!query_count[0] && !query_count[1] && !reset_assertions);

    initialize();
    mirror_orders = 0;
    host_regs[0][LSD_DMA_READ / 4] = 0x00800001;
    host_regs[0][LSD_DMA_WRITE / 4] = 0x00804001;
    assert(sd_shared_clock(clock_sample, &input) == 0);
    assert(query_count[0] == 2 && !query_count[1]);
    assert(!reset_assertions);

    puts("SDIO adapter: dual ownership, clocks, DMA isolation and read-only policy PASS");
    return 0;
}

#endif
